+import express from "express";
+import { claimNext, completeJob } from "./jobs.ts";
+
+const app = express();
+app.use(express.json());
+
+app.get("/api/jobs/next", async (req, res) => {
+  try {
+    const job = await claimNext();
+    if (job === null) {
+      return res.status(204).send();
+    }
+    res.json(job);
+  } catch (error) {
+    console.error("Error claiming job:", error);
+    res.status(500).json({ error: "Failed to claim job" });
+  }
+});
+
+app.post("/api/jobs/:jobId/complete", async (req, res) => {
+  try {
+    await completeJob(req.params.jobId);
+    res.status(204).send();
+  } catch (error) {
+    console.error("Error completing job:", error);
+    res.status(500).json({ error: "Failed to complete job" });
+  }
+});
+
+const PORT = process.env.PORT || 3000;
+app.listen(PORT, () => {
+  console.log(`Job queue API server running on port ${PORT}`);
+});
